import { ChangeDetectionStrategy, Component, inject } from '@angular/core';

import { ExperienceHubComponent } from '../sections/experience-hub.component';
import { PlatformStripComponent } from '../sections/platform-strip.component';

import { SeoService } from '../core/seo.service';
import {
  DirectoryComponent,
  FlagshipComponent,
  GlobalLocationsMapComponent,
  HeroComponent,
  HostCredibilityComponent,
  IndustriesComponent,
  OutcomesComponent,
  NewCategoryComponent,
  InsightsSectionComponent,
  MarqueeComponent,
  SatisfactionGuaranteeComponent,
  TrustBarComponent,
  TestimonialsComponent,
  TrustedByComponent,
  WhyComponent,
} from '../sections';

/** The original `<title>` and meta description, kept byte-for-byte. */
const TITLE = 'Managed Cloud & Cybersecurity Services India | XcellHost';
const DESCRIPTION =
  'XcellHost — Mumbai-based managed cloud & cybersecurity provider since 1999. Tally on Cloud, ' +
  'Acronis Backup, DPDPA compliance & 24/7 SOC. ISO 27001 certified.';

/**
 * The routed homepage: every section stacked in the order the original
 * document had them, between the header and the footer of the app shell.
 */
@Component({
  selector: 'xh-home-page',
  standalone: true,
  imports: [
    HeroComponent,
    TrustBarComponent,
    MarqueeComponent,
    FlagshipComponent,
    DirectoryComponent,
    HostCredibilityComponent,
    WhyComponent,
    IndustriesComponent,
    OutcomesComponent,
    NewCategoryComponent,
    ExperienceHubComponent,
    PlatformStripComponent,
    InsightsSectionComponent,
    GlobalLocationsMapComponent,
    SatisfactionGuaranteeComponent,
    TestimonialsComponent,
    TrustedByComponent,
  ],
  host: { style: 'display:contents' },
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <xh-hero />
    <xh-trust-bar />
    <xh-marquee />
    <xh-flagship />
    <xh-host-credibility />
    <xh-why />
    <xh-outcomes />
    <xh-new-category />
    <xh-platform-strip />
    <xh-experience-hub />
    <xh-directory />
    <xh-trusted-by />
    <xh-industries />
    <xh-insights-section [caseStudyLimit]="3" />
    <xh-testimonials />
    <xh-global-locations-map />
    <xh-satisfaction-guarantee />
  `,
})
export class HomePage {
  constructor() {
    inject(SeoService).set(TITLE, DESCRIPTION, '/');
  }
}
