import { ChangeDetectionStrategy, Component, signal } from '@angular/core';

import { RevealDirective } from '../shared/reveal.directive';

interface DataCenterLocation {
  readonly flag: string;
  readonly code: string;
  readonly name: string;
}

const DATA_CENTER_LOCATIONS: readonly DataCenterLocation[] = [
  { flag: '🇮🇳', code: 'IN', name: 'India' },
  { flag: '🇺🇸', code: 'US', name: 'United States' },
  { flag: '🇬🇧', code: 'GB', name: 'United Kingdom' },
  { flag: '🇨🇦', code: 'CA', name: 'Canada' },
  { flag: '🇩🇪', code: 'DE', name: 'Germany' },
  { flag: '🇦🇺', code: 'AU', name: 'Australia' },
  { flag: '🇫🇷', code: 'FR', name: 'France' },
  { flag: '🇦🇪', code: 'AE', name: 'Dubai (UAE)' },
  { flag: '🇸🇬', code: 'SG', name: 'Singapore' },
  { flag: '🇭🇰', code: 'HK', name: 'Hong Kong' },
  { flag: '🇳🇱', code: 'NL', name: 'Netherlands' },
];

const ACRONIS_REGIONS = [
  { name: 'Americas', locations: [{ name: 'Ashburn (VA), United States', code: 'US' }, { name: 'Phoenix (AZ), United States', code: 'US' }, { name: 'Quer\u00e9taro, Mexico', code: 'MX' }, { name: 'Sao Paulo, Brazil', code: 'BR' }, { name: 'Toronto, Canada', code: 'CA' }, { name: 'Vancouver, Canada', code: 'CA' }] },
  { name: 'Europe', locations: [{ name: 'Berlin, Germany', code: 'DE' }, { name: 'Billund, Denmark', code: 'DK' }, { name: 'Frankfurt, Germany', code: 'DE' }, { name: 'Gothenburg, Sweden', code: 'SE' }, { name: 'Helsinki, Finland', code: 'FI' }, { name: 'Istanbul, T\u00fcrkiye', code: 'TR' }, { name: 'Liechtenstein', code: 'LI' }, { name: 'Lisbon, Portugal', code: 'PT' }, { name: 'London, United Kingdom', code: 'GB' }, { name: 'Lupfig, Switzerland', code: 'CH' }, { name: 'Oslo, Norway', code: 'NO' }, { name: 'Prague, Czech Republic', code: 'CZ' }] },
  { name: 'Asia Pacific', locations: [{ name: 'Auckland, New Zealand', code: 'NZ' }, { name: 'Jakarta, Indonesia', code: 'ID' }, { name: 'Kanagawa, Japan', code: 'JP' }, { name: 'Kuala Lumpur, Malaysia', code: 'MY' }, { name: 'Mumbai, India', code: 'IN' }, { name: 'Nagano, Japan', code: 'JP' }, { name: 'Seoul, Korea', code: 'KR' }, { name: 'Singapore', code: 'SG' }, { name: 'Sydney, Australia', code: 'AU' }, { name: 'Taipei, Taiwan', code: 'TW' }] },
  { name: 'Middle East', locations: [{ name: 'Abu Dhabi, UAE', code: 'AE' }] },
  { name: 'Africa', locations: [{ name: 'Johannesburg, South Africa', code: 'ZA' }] },
] as const;

/** Global datacenter network presented between homepage insights and guarantees. */
@Component({
  selector: 'xh-global-locations-map',
  standalone: true,
  imports: [RevealDirective],
  host: { style: 'display:contents' },
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <section class="data-centers" aria-labelledby="data-centers-title">
      <div class="wrap">
        <header class="sec-head" xhReveal>
          <div class="eyebrow">Global infrastructure</div>
          <h2 id="data-centers-title">Global Data Centers</h2>
          @if (activeView() === 'xcellhost') {
            <p>
              Our globally distributed facilities use advanced technology to provide secure,
              stable environments with the performance and reliability your business depends on.
            </p>
          } @else {
            <p>
              Explore the Acronis Cyber Cloud footprint and the regional infrastructure options
              available for cyber protection and data residency.
            </p>
          }
          <div class="dc-view-switch" role="tablist" aria-label="Choose a data center network">
            <button
              type="button"
              role="tab"
              [class.active]="activeView() === 'xcellhost'"
              [attr.aria-selected]="activeView() === 'xcellhost'"
              aria-controls="xcellhost-dcs"
              (click)="activeView.set('xcellhost')"
            >View XcellHost Global DC’s</button>
            <button
              type="button"
              role="tab"
              [class.active]="activeView() === 'acronis'"
              [attr.aria-selected]="activeView() === 'acronis'"
              aria-controls="acronis-dcs"
              (click)="activeView.set('acronis')"
            >View Acronis Global DC’s</button>
          </div>
        </header>

        @if (activeView() === 'xcellhost') {
        <div id="xcellhost-dcs" class="dc-tab-panel" role="tabpanel" aria-label="XcellHost data centers">
        <div class="map-stage">
          <iframe
            class="global-dc-globe"
            src="/assets/animations/xcellhost-globe.html?mode=globe"
            title="Interactive globe showing XcellHost data center locations"
            scrolling="no"
            loading="eager"
          ></iframe>
        </div>

        <div class="location-marquee" aria-label="Datacenter regions" xhReveal>
          <div class="location-track">
            @for (pass of passes; track pass) {
              @for (location of locations; track location.code) {
                <div class="location-chip" [attr.aria-hidden]="pass === 1 ? 'true' : null">
                  <img class="location-flag" [src]="flagUrl(location.code)" [alt]="location.name + ' flag'" loading="lazy" />
                  <strong>{{ location.name }}</strong>
                </div>
              }
            }
          </div>
        </div>
        </div>
        } @else {
        <div id="acronis-dcs" class="dc-tab-panel" role="tabpanel" aria-label="Acronis data centers">
          <div class="acronis-regions">
            @for (region of acronisRegions; track region.name) {
              <details class="acronis-region" [class.acronis-africa]="region.name === 'Africa'" [attr.aria-label]="region.name">
                <summary><span class="region-heading"><strong>{{ region.name }}</strong><small>{{ region.locations.length }} {{ region.locations.length === 1 ? 'location' : 'locations' }}</small></span><span class="region-toggle" aria-hidden="true"></span></summary>
                <ul>
                  @for (location of region.locations; track location.name) {
                    <li><img class="acronis-country-flag" [src]="flagUrl(location.code)" alt="" width="22" height="16" loading="lazy" /><span>{{ location.name }}</span></li>
                  }
                </ul>
              </details>
            }
          </div>
        </div>
        }
      </div>
    </section>
  `,
  styles: `
    .acronis-regions { display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px;margin-top:36px;text-align:left;align-items:start; }
    .acronis-region { border:1px solid #cbdaf0;border-radius:14px;background:transparent;overflow:hidden;transition:border-color .2s; }
    .acronis-region:hover { border-color:#79a6e8; }
    .acronis-region[open] { border-color:#1565d8; }
    .acronis-region summary { min-height:116px;padding:20px 16px;display:flex;align-items:center;justify-content:space-between;gap:10px;cursor:pointer;list-style:none;color:var(--navy); }
    .acronis-region summary::-webkit-details-marker { display:none; }
    .acronis-region summary:focus-visible { outline:2px solid var(--blue);outline-offset:-4px;border-radius:14px; }
    .region-heading { display:flex;flex-direction:column;gap:8px; }
    .region-heading strong { font:600 14px/1.4 var(--body); }
    .region-heading small { font:500 11px/1.3 var(--body);color:#647a99;letter-spacing:.03em; }
    .region-toggle { position:relative;width:26px;height:26px;flex-shrink:0;border-radius:50%;background:#e1ebfc;color:#1565d8; }
    .region-toggle::before,.region-toggle::after { content:'';position:absolute;left:8px;top:12px;width:10px;height:2px;background:currentColor;border-radius:2px; }
    .region-toggle::after { transform:rotate(90deg); }
    .acronis-region[open] .region-toggle { background:#1565d8;color:#fff; }
    .acronis-region[open] .region-toggle::after { display:none; }
    .acronis-region[open] summary { border-bottom:1px solid #cfdef1; }
    .acronis-region ul { list-style:none;margin:0;padding:10px 16px 16px; }
    .acronis-region li { display:flex;align-items:flex-start;gap:8px;padding:10px 0;color:var(--slate);font:400 13px/1.55 var(--body); }
    .acronis-country-flag { width:22px;height:16px;object-fit:contain;flex-shrink:0;margin-top:2px; }
    @media(max-width:1000px) { .acronis-regions { grid-template-columns:repeat(2,minmax(0,1fr)); } }
    @media(max-width:540px) { .acronis-regions { grid-template-columns:1fr;gap:10px; }.acronis-region summary { min-height:80px; } }

    .data-centers {
      position: relative;
      padding: 76px 0;
      overflow: hidden;
      border-block: 1px solid var(--line);
      background:
        radial-gradient(circle at 92% 8%, rgba(21, 101, 216, 0.11), transparent 28%),
        var(--ice);
    }

    .data-centers .sec-head {
      max-width: 820px;
      margin: 0 auto 26px;
      text-align: center;
    }

    .data-centers .eyebrow {
      display: inline-block;
    }

    .data-centers .eyebrow::after {
      margin-inline: auto;
    }

    .dc-view-switch {
      display: inline-flex;
      gap: 5px;
      margin-top: 22px;
      padding: 5px;
      border: 1px solid #c9d8ed;
      border-radius: 999px;
      background: rgba(255, 255, 255, .78);
      box-shadow: 0 8px 22px rgba(4, 30, 66, .08);
    }

    .dc-view-switch button {
      min-height: 42px;
      padding: 9px 19px;
      border: 0;
      border-radius: 999px;
      background: transparent;
      color: var(--slate);
      font: 700 13px/1 var(--body);
      cursor: pointer;
      transition: background .2s, color .2s, box-shadow .2s, transform .2s;
    }

    .dc-view-switch button:hover { color: var(--blue); }
    .dc-view-switch button.active {
      background: var(--blue);
      color: #fff;
      box-shadow: 0 7px 16px rgba(21, 101, 216, .25);
    }
    .dc-view-switch button:focus-visible { outline: 3px solid rgba(21, 101, 216, .25); outline-offset: 2px; }

    .dc-tab-panel { animation: dc-panel-in .35s ease both; }
    @keyframes dc-panel-in { from { opacity: 0; transform: translateY(8px); } }

    .map-stage {
      display: grid;
      max-width: 1180px;
      margin: 0 auto;
      grid-template-columns: minmax(0, 1fr);
      align-items: center;
      isolation: isolate;
    }

    .location-count {
      display: flex;
      align-items: flex-start;
      flex-direction: column;
      gap: 6px;
    }

    .location-count strong {
      color: var(--navy);
      font: 800 clamp(52px, 7vw, 78px) / 0.92 var(--disp);
      letter-spacing: -0.06em;
    }

    .location-count span {
      padding: 7px 13px;
      border-radius: 5px;
      background: var(--orange);
      color: #fff;
      font: 600 14px/1 var(--mono);
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .map-stage .global-dc-globe {
      position: relative;
      z-index: 1;
      display: block;
      width: min(100%, 720px);
      height: clamp(430px, 65vw, 720px);
      margin: 0 auto;
      border: 0;
      overflow: hidden;
      background: transparent;
    }

    .location-marquee {
      width: 100%;
      margin-top: 12px;
      overflow: hidden;
      mask-image: linear-gradient(90deg, transparent, #000 5%, #000 95%, transparent);
      -webkit-mask-image: linear-gradient(90deg, transparent, #000 5%, #000 95%, transparent);
    }

    .location-track {
      display: flex;
      width: max-content;
      gap: 14px;
      padding: 10px 7px;
      animation: locations-scroll 34s linear infinite;
    }

    .location-marquee:hover .location-track {
      animation-play-state: paused;
    }

    .location-chip {
      display: flex;
      min-width: 176px;
      min-height: 58px;
      align-items: center;
      gap: 12px;
      padding: 10px 18px;
      border: 1px solid var(--line);
      border-radius: 12px;
      background: #fff;
      box-shadow: 0 7px 20px rgba(4, 30, 66, 0.06);
    }

    .location-flag {
      flex: 0 0 auto;
      width: 34px;
      height: 23px;
      display: inline-block;
      overflow: hidden;
      border-radius: 3px;
      box-shadow: 0 1px 4px rgba(4, 30, 66, .18);
      object-fit: cover;
    }

    .location-chip strong {
      overflow: hidden;
      color: var(--navy);
      font: 600 13px/1.3 var(--body);
      text-overflow: ellipsis;
    }

    .acronis-location-track { animation-duration: 80s; }
    .acronis-source {
      display: block;
      width: max-content;
      margin: 10px auto 0;
      color: var(--blue);
      font: 700 12px/1.3 var(--body);
      text-decoration: none;
    }
    .acronis-source:hover { text-decoration: underline; }

    @keyframes locations-scroll {
      to {
        transform: translateX(calc(-50% - 7px));
      }
    }

    @media (max-width: 720px) {
      .data-centers {
        padding: 56px 0;
      }

      .map-stage {
        grid-template-columns: 1fr;
      }

      .location-count {
        position: relative;
        z-index: 1;
        width: max-content;
        margin: 0 auto -18px;
        align-items: center;
      }

      .dc-view-switch { width: 100%; }
      .dc-view-switch button { flex: 1; padding-inline: 10px; }
    }

    @media (max-width: 430px) {
      .map-stage {
        margin-inline: -10px;
      }

      .location-chip {
        min-width: 160px;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      .location-track {
        animation: none;
      }
      .dc-tab-panel { animation: none; }
    }
  `,
})
export class GlobalLocationsMapComponent {
  readonly locations = DATA_CENTER_LOCATIONS;
  readonly acronisRegions = ACRONIS_REGIONS;
  readonly passes = [0, 1];
  readonly activeView = signal<'xcellhost' | 'acronis'>('xcellhost');

  flagUrl(code: string): string {
    return `https://flagcdn.com/w40/${code.toLowerCase()}.png`;
  }
}
